node <<'JS'
const fs = require('node:fs');
const original = fs.readFileSync;
fs.readFileSync = function(file, ...args) {
  let result = original.call(this, file, ...args);
  if (typeof file === 'string' && /workflows\/(ci|review-acceptance)\.yml$/.test(file)) {
    result = result.replace(/(actions\/checkout|docker\/setup-buildx-action)@[0-9a-f]{40}[^\n]*/g, '$1@' + 'a'.repeat(40) + ' # v99');
  }
  return result;
};
require('./.github/scripts/ci-job-consistency.test.cjs');
